class Solution { public String reverseParentheses(String s){Deque<StringBuilder> stack=new ArrayDeque<>();StringBuilder current=new StringBuilder();for(char ch:s.toCharArray())if(ch=='('){stack.push(current);current=new StringBuilder();}else if(ch==')'){current.reverse();StringBuilder outer=stack.pop();outer.append(current);current=outer;}else current.append(ch);return current.toString();} }
